 $('#viewport').prepend(canvas);resize.disconnect();resize.observe($('#viewport'));$('#name').value=vehicle()?.name||'';if(isShip)document.body.classList.add('ship-editor');$('#palette').querySelector(`[data-tool="${tool}"]`)?.classList.add('selected');rebuild();filterCatalog();status();
