function rebuild(){if(model)disposeAircraft(model);spec=compileAircraft(vehicle(),{validate:false});model=aircraftModel(spec);model.position.copy(spec.com);scene.add(model);model.updateMatrixWorld(true);const v=vehicle(),errors=validateVehicle(v),tris=blueprintTriangles(v);if(isShip){$('#statistics').innerHTML=`<b>${shipClasses[v.shipClass].name} · 核心 ${shipCoreCount(v)} / ${shipClasses[v.shipClass].cores}</b><span>${v.blocks.length} 半边方块 · ${v.parts.length} 附件 · ${tris} 三角面</span><span>航速 ${v.cruiseSpeed} m/s · 舰体 ${Math.round(spec.mass/1000)} 吨</span><small>${exposedShipCores(v)?'提示：有 '+exposedShipCores(v)+' 个核心直接暴露，可加装装甲':'核心区周围已有结构包裹'}</small><small class="${errors.length?'error':'ok'}">${errors.length?errors.map(esc).join('；'):'✓ 核心与连接检查通过，可投入战斗'}</small>`;}else $('#statistics').innerHTML=`<b>${v.blocks.length} 半边方块 · ${v.parts.length} 附件</b><span>${tris} / 10000 三角面 · ${Math.round(spec.mass)}kg</span><span>${spec.powerHp}马力 · ${spec.wingArea.toFixed(1)}m²升力面积</span><span>${spec.dragArea.toFixed(2)}m²等效阻力 · 正面${spec.frontalArea.toFixed(2)}m² · 失速约${Math.round(spec.stallSpeed*3.6)}km/h</span><small class="${errors.length?'error':'ok'}">${errors.length?errors.map(esc).join('；'):'✓ 机体连通，可试飞'}</small>`;$('#outliner').innerHTML=v.parts.map(p=>`<button data-select="${p.id}" class="${selected?.id===p.id?'selected':''}">${editorLabel(partKit[p.type].name)}<small>${p.offset.join(', ')}m${p.mirrorOf?' · 对称副本':''}</small></button>`).join('')||'<small>选取功能附件，再瞄准机体放置。</small>';properties();soundSettings();if(isShip&&coreView)applyCoreView();}
function navalWeaponProperties(p){const d=partKit[p.type],profile=loadingProfile(d);return `<p>弹匣 ${profile.capacity} 发 · ${profile.burst} 发点射 · 装填 ${profile.reload} 秒</p><label>对舰弹种<select data-prop="surfaceAmmo">${[['ap','穿甲弹'],['he','高爆弹']].map(([k,n])=>`<option value="${k}" ${p.surfaceAmmo===k?'selected':''}>${n}</option>`).join('')}</select></label><p>${d.caliber>=203?'瞄准飞机自动装填三式对空弹；已装弹不会随目标切换而卸除。':'瞄准飞机自动使用防空弹；轻型防空炮采用弹匣点射。'}</p><label>防空引信<select data-prop="fuze">${[['impact','碰炸'],['timed','定时空爆'],['proximity','近炸']].map(([k,n])=>`<option value="${k}" ${p.fuze===k?'selected':''}>${n}</option>`).join('')}</select></label><label>近炸触发距离（米）<input data-prop="proximityRadius" type="number" min="2" max="120" value="${p.proximityRadius}"></label><small>射程 ${d.range/1000} km · 203毫米及以上主炮对空使用近炸三式弹，产生燃烧锥形区域。</small>`;}
function properties(){const p=vehicle().parts.find(p=>p.id===selected?.id),b=selected?.cell&&vehicle().blocks.find(b=>cellKey(b.cell)===cellKey(selected.cell));$('#properties').innerHTML=p?`<h3>${editorLabel(partKit[p.type].name)}</h3><label>颜色<input data-prop="color" type="color" value="${p.color}"></label>${partFamily(p.type)==='gear'?`<label>折叠方向<select data-prop="gearFoldDirection">${[['forward','向前'],['backward','向后'],['inward','向内'],['outward','向外']].map(([k,n])=>`<option value="${k}" ${p.gearFoldDirection===k?'selected':''}>${n}</option>`).join('')}</select></label><small>放下投影 ${spec.gearProjections.at(-1).area.toFixed(2)}m² / 收起 ${spec.gearProjections[0].area.toFixed(2)}m²</small><button data-command="gear-preview">预览起落架收放 / 轮子滚动</button>`:''}${['gun','turret'].includes(partFamily(p.type))?`<small>${partKit[p.type].caliber||12.7}mm · ${Math.round((partKit[p.type].rate||7)*60)}发/分 · ${partKit[p.type].ammo||600}发 · 炮管后坐与弹道下坠</small>${partFamily(p.type)==='turret'?['yawRate','pitchRate','traverseAcceleration'].map((k,i)=>`<label>${['水平转速（度/秒）','俯仰转速（度/秒）','转动加速度'][i]}<input data-prop="${k}" type="number" min="1" max="${i===2?720:i===0?turretRateLimits(partKit[p.type]).yaw:turretRateLimits(partKit[p.type]).pitch}" value="${p[k]??normalizeWeaponSettings(p,partKit[p.type])[k]}"></label>`).join(''):''}`:''}${['engine','shipEngine'].includes(partFamily(p.type))?`<label>马力<input type="number" data-prop="powerHp" value="${p.powerHp}" min="50" max="${isShip?200000:3000}" step="10"></label>`:''}${isShip&&partFamily(p.type)==='turret'?navalWeaponProperties(p):''}<label>倍率<input type="number" data-prop="scale" min=".25" max="2" step=".05" value="${p.scale}"></label>${[0,1,2].map(i=>`<label>${['横向X','高度Y','前后Z'][i]}（m）<input data-vector="offset" data-axis="${i}" type="number" step="${gridSize}" min="${isShip?-1024:-32}" max="${isShip?1024:32}" value="${p.offset[i]}"></label><label>${['俯仰','偏航','滚转'][i]}角<input data-vector="rotation" data-axis="${i}" type="number" step="15" min="-180" max="180" value="${p.rotation[i]}"></label>`).join('')}<button data-command="copy-mirror">在对面复制此附件</button><button data-command="delete">拆除此附件</button><small>对称副本创建后可独立编辑。炮塔会在射界内转动、瞄准并开火。</small>`:b?`<h3>${editorLabel(blockKit[b.kind].name)}</h3><p>网格 ${b.cell.join(', ')} · 自动对称 · 单块耐久 ${Math.max(isShip?500:10,Math.round(blockKit[b.kind].hp*shapeKit[b.shape||'cube'].volume))}</p><label>形状<select data-block-shape>${Object.entries(shapeKit).map(([k,d])=>`<option value="${k}" ${b.shape===k?'selected':''}>${editorLabel(d.name)}</option>`).join('')}</select></label>${[0,1,2].map(i=>`<label>${['俯仰','偏航','滚转'][i]}<input type="number" step="90" min="-180" max="180" data-block-rotation="${i}" value="${b.shapeRotation?.[i]||0}"></label>`).join('')}<label>颜色<input type="color" data-block-color value="${b.color}"></label><button data-command="delete">拆除方块与对称方块</button>`:'<p>中键选取方块或附件，查看颜色、位置、方向及功能参数。</p>';}
function filterCatalog(){const q=($('#search')?.value||'').toLowerCase();$('#palette').querySelectorAll('[data-tool]').forEach(b=>{const k=b.dataset.tool,d=blocksForEditor[k]||partKit[k],family=partFamily(k),category=d.category||(blocksForEditor[k]?'structure':['gun','turret','bomb'].includes(family)?'weapons':family==='engine'?'engine':family==='gear'?'gear':'structure');b.hidden=(catalogCategory!=='all'&&catalogCategory!==category)||!b.textContent.toLowerCase().includes(q)&&!k.includes(q);});}
function applyCoreView(){for(const p of spec.parts){const m=model.userData.models.get(p.id);m.traverse(o=>{if(!o.material||o.userData.runtimeEffect)return;const fade=coreView&&p.blockKind!=='ship_core';o.material.transparent=fade;o.material.opacity=fade?.12:1;o.material.depthWrite=!fade;});}}
function soundSettings(){const types=[...new Set(vehicle().parts.filter(p=>['gun','turret'].includes(partFamily(p.type))).map(p=>p.type))];$('#weapon-sounds').innerHTML=`<h3>当前${unitName} · 武器开火音效</h3><p class="tip">${isShip?'按型号设置，仅应用于当前战舰；各炮位独立转动、俯仰和装填。':'按型号设置，仅应用于当前飞机。副炮在目标距离不超过 2 公里时开火。'}</p>${types.map(type=>`<label>${esc(partKit[type].name)}<select data-fire-sound="${type}"><option value="">内置炮声</option>${assetsOfType(project,'effect').map(a=>`<option value="${esc(a.id)}" ${vehicle().fireSounds?.[type]===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label><div class="sound-actions"><button data-upload-sound="${type}">上传音效</button><button data-listen-sound="${type}">试听</button></div>`).join('')||'<p class="tip">安装机枪、机炮或炮塔后可设置。</p>'}`;}
let soundPreview=null;
async function uploadSound(type){const result=await bridge('importAsset',{type:'audio',single:true});if(!result?.length)return;history.begin();for(const asset of result)project.assets.push({...asset,audioKind:'effect',folderId:''});vehicle().fireSounds||={};vehicle().fireSounds[type]=result[0].id;history.commit({label:'上传当前飞机机炮音效'});dirty=true;soundSettings();status();}
async function portableFile(command){
 if(command==='export-file'){const errors=validateVehicle(vehicle());if(errors.length)throw Error(errors.join('；'));const result=await bridge('exportVehicleFile',{vehicleType:isShip?'warship':'aircraft',blueprint:structuredClone(vehicle()),assets:project.assets.filter(a=>Object.values(vehicle().fireSounds||{}).includes(a.id))});if(result)notice(unitName+'与 '+result.audioCount+' 份武器音效已导出。');return result;}
 const result=await bridge('importVehicleFile',{vehicleType:isShip?'warship':'aircraft'});if(!result)return;const blueprint=normalizeVehicle(result.blueprint),errors=validateVehicle(blueprint);if(errors.length)throw Error(errors.join('；'));if(blueprintTriangles(blueprint)>(isShip?60000:10000))throw Error('导入飞机超过10000三角面');if(dirty)await save();history.begin();const d=(isShip?createShipDocument:createVehicle)(project,blueprint.name,blueprint);project.assets.push(...result.assets);currentId=d.id;selected=null;dirty=true;history.commit({label:'导入独立飞机'});render();frame();notice('飞机及机炮音效已导入工程，点击保存写入工程包。');return d;
}
function mutate(label,fn){if(saving)return;history.begin();const before=structuredClone(vehicle());try{fn();doc().blueprint=normalizeVehicle(vehicle());if(vehicle().blocks.some(b=>b.cell[0]===0&&!shapeSymmetricX(b.shape,b.shapeRotation)))throw Error('中心线的异形块必须保持左右对称');doc().blueprint.vehicleId=currentId;doc().name=vehicle().name;if(blueprintTriangles(vehicle())>(isShip?60000:10000))throw Error('整机超过10000三角面，请减少附件或方块');history.commit({label});dirty=JSON.stringify(project)!==JSON.stringify(baseline);rebuild();status();}catch(error){doc().blueprint=before;rebuild();notice(error.message,true);}}
async function save(){if(saving)return;history.seal();saving=true;status();try{applyVehicle(project,doc());const result=await bridge('saveModule',{base:baseline,project:structuredClone(project)});project=result.project;baseline=structuredClone(project);dirty=false;history.reset();rebuild();status();notice('载具文件已保存，引用它的空战幕已同步。');return {saved:true};}finally{saving=false;status();if(queued){const next=queued;queued=null;refresh(next);}}}
function refresh(payload){if(!project)return;if(saving){queued=payload;return;}const latest=payload.project||payload;if(latest.id!==project.id){notice('主窗口已切换工程，请重新打开载具编辑器',true);return;}try{project=mergeEditorProject(baseline,latest,project);baseline=structuredClone(latest);ensureVehicleLibrary(project);if(isShip)ensureShipLibrary(project);if(!doc())currentId=project.vehicles.find(v=>(v.vehicleType==='warship')===isShip).id;dirty=JSON.stringify(project)!==JSON.stringify(baseline);history.reset();rebuild();status();}catch(error){notice(error.message+'；当前修改仍保留',true);}}
function frame(){document.exitPointerLock?.();if(isShip&&$('#viewport').clientHeight){camera.aspect=$('#viewport').clientWidth/$('#viewport').clientHeight;camera.updateProjectionMatrix();}const bounds=new THREE.Box3().setFromObject(model),center=bounds.getCenter(new THREE.Vector3()),size=bounds.getSize(new THREE.Vector3()).length();camera.position.copy(center).add(new THREE.Vector3(.68,.48,-.75).multiplyScalar(Math.max(10,size*.95)));camera.lookAt(center);if(isShip){const inverse=camera.quaternion.clone().invert(),tan=Math.tan(camera.fov*Math.PI/360);let distance=0;for(const x of [bounds.min.x,bounds.max.x])for(const y of [bounds.min.y,bounds.max.y])for(const z of [bounds.min.z,bounds.max.z]){const p=new THREE.Vector3(x,y,z).sub(center).applyQuaternion(inverse);distance=Math.max(distance,p.z+Math.abs(p.x)/(tan*camera.aspect),p.z+Math.abs(p.y)/tan);}camera.position.copy(center).addScaledVector(new THREE.Vector3(.68,.48,-.75).normalize(),distance*1.2);camera.lookAt(center);}look.yaw=camera.rotation.y;look.pitch=camera.rotation.x;}
async function open(id){if(id===currentId)return;if(dirty)await save();currentId=id;selected=null;const d=doc();if(!isShip&&(d.blueprint.schemaVersion!==2||d.blueprint.gridSize!==.125)){d.blueprint=vehicleFromAircraft(d.blueprint);d.blueprint.vehicleId=id;dirty=true;}history.reset();air.cancel();battle=false;render();frame();const recent=JSON.parse(localStorage.getItem(recentKey())||'[]');localStorage.setItem(recentKey(),JSON.stringify([id,...recent.filter(x=>x!==id)].slice(0,12)));notice(dirty?'机体已细化到12.5厘米网格，保存后应用。':'已打开 '+d.name);}
