function chooseHit(){let obj=target.hit?.object;while(obj&&!obj.userData.partId)obj=obj.parent;if(!obj)return null;const id=obj.userData.partId;if(!id.startsWith('cell:'))return {id};const cell=snapCell(target.hit.point.clone().addScaledVector(target.hit.face.normal.clone().transformDirection(target.hit.object.matrixWorld),-.015).toArray(),vehicle().gridSize);if(cell[0]<0){notice('左半边由右半边自动生成，请到X≥0一侧编辑',true);return null;}return {cell};}
