document.addEventListener('keydown',e=>{if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||battle)return;const key=e.key.toLowerCase();if(e.ctrlKey&&['s','o','n','z','y'].includes(key)&&document.pointerLockElement!==canvas){e.preventDefault();command(key==='s'?'save':key==='o'?'open':key==='n'?'new':key==='y'||e.shiftKey?'redo':'undo').catch(error=>notice(error.message,true));return;}if(document.pointerLockElement===canvas){if(['KeyW','KeyA','KeyS','KeyD','Space','ControlLeft','ControlRight','ShiftLeft','ShiftRight'].includes(e.code)){e.preventDefault();keys.add(e.code);}if(['KeyT','KeyY'].includes(e.code)&&!e.repeat){const axis=e.code==='KeyT'?0:2;blockRotation[axis]=((blockRotation[axis]+270)%360)-180;notice('形状旋转 '+blockRotation.join(', ')+'°');}if(e.code==='KeyR'&&!e.repeat){attachYaw=((attachYaw+270)%360)-180;blockRotation[1]=attachYaw;notice('附件偏航 '+attachYaw+'°');}}});document.addEventListener('keyup',e=>keys.delete(e.code));
